// Generated by vibelang from src/internal/backend/Destination.ts; the migrate flow writes it again with each batch.
/**
 * Chooses where a CLI command runs: the configured install or the local project.
 *
 * @since 1.0.0
 */
import { Session } from "./Session.js";
/**
 * Whether a command targets the configured install rather than local state.
 * Explicit local scope wins over both a destination flag and saved install settings.
 *
 * @since 1.0.0
 * @private
 */
export const targetsInstall = (context, runtime) => {
    const { args, options } = context;
    if (["root", "data", "flow"].some((key) => options[key] !== undefined) || args.path !== undefined)
        return false;
    if (options.repo !== undefined || options.cloud === true)
        return true;
    // Run IDs belong to a host, not to the saved login. Never redirect a local
    // run operation merely because an install has been configured.
    if (args.run !== undefined)
        return false;
    const env = runtime.environment ?? process.env;
    // A credential authenticates a destination; it does not configure one.
    return !!new Session(env).config().api_origin;
};
